285	    /**
286	     * Builds the customer code for a newly created owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
287	     * where {@code CITY3} is the upper-cased first three letters of the owner's city, {@code LAST3}
288	     * is the upper-cased first three letters of the owner's last name, and {@code NNNN} is a per-city
289	     * 4-digit zero-padded sequence equal to one more than the number of owners already in that city.
290	     * For example an owner named "Smithers" in "Springfield" created when 10 owners already live in
291	     * Springfield gets {@code 'SPR-SMI-0011'}.
292	     *
293	     * @param city the owner's city
294	     * @param lastName the owner's last name
295	     * @return the assigned customer code
296	     */
297	    /**
298	     * Counts how many existing owners share the given first and last name, compared
299	     * case-insensitively, at the moment before the new owner is persisted. The result is
300	     * stored on the owner as its {@code namesakeCount}, so it reflects the population as it
301	     * stood when the owner was created rather than being recomputed on later reads.
302	     *
303	     * @param firstName the first name of the owner being created
304	     * @param lastName the last name of the owner being created
305	     * @return the number of pre-existing owners with the same first and last name
306	     */
307	    private int countNamesakes(String firstName, String lastName) {
308	        String first = firstName == null ? "" : firstName;
309	        String last = lastName == null ? "" : lastName;
310	        return (int) this.clinicService.findAllOwners().stream()
311	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
312	                && last.equalsIgnoreCase(existing.getLastName()))
313	            .count();
314	    }
315	
316	    private String nextCustomerCode(String city, String lastName) {
317	        String cityLetters = city == null ? "" : city;
318	        String city3 = cityLetters.substring(0, Math.min(3, cityLetters.length())).toUpperCase(Locale.ROOT);
319	        String letters = lastName == null ? "" : lastName;
320	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
321	        String normalizedCity = normalizeForComparison(city);
322	        int sequence = (int) this.clinicService.findAllOwners().stream()
323	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
324	            .count() + 1;
325	        return String.format("%s-%s-%04d", city3, last3, sequence);
326	    }
327	
328	    /**
329	     * Rejects an owner payload that is missing or blank in any of the required fields
330	     * (firstName, lastName, address, city, telephone). The bean-validation constraints on
331	     * {@link OwnerFieldsDto} already reject {@code null} values and most malformed input, but
332	     * a present-yet-blank {@code address} or {@code city} would otherwise slip through, so this
333	     * guard enforces the rule uniformly for every required field.
334	     *
335	     * @param ownerFieldsDto the submitted owner payload
336	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
337	     */
338	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
339	        List<String> invalidFields = new ArrayList<>();
340	        if (isBlank(ownerFieldsDto.getFirstName())) {
341	            invalidFields.add("firstName");
342	        }
343	        if (isBlank(ownerFieldsDto.getLastName())) {
344	            invalidFields.add("lastName");
345	        }
346	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
347	            invalidFields.add("address");
348	        }
349	        if (isBlank(ownerFieldsDto.getCity())) {
350	            invalidFields.add("city");
351	        }
352	        if (isBlank(ownerFieldsDto.getTelephone())) {
353	            invalidFields.add("telephone");
354	        }
355	        if (!invalidFields.isEmpty()) {
356	            throw new InvalidOwnerFieldsException(invalidFields);
357	        }
358	    }
359	
360	    private boolean isBlank(String value) {
361	        return value == null || value.isBlank();
362	    }
363	
364	    /**
365	     * Validates a supplied owner postcode. The postcode is optional: a {@code null} value is
366	     * accepted and the request stays backward-compatible. When present it must be a 4-digit value,
367	     * and must fall within the inclusive range allowed for the owner's city region per the fixed
368	     * {@link #CITY_REGION} / {@link #REGION_POSTCODES} tables (NSW 2000-2099, VIC 3000-3099,
369	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode. The value is stored
370	     * and returned exactly as given.
371	     *
372	     * @param postcode the submitted postcode, may be {@code null} when absent
373	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
374	     * @throws InvalidOwnerFieldsException if a present postcode is not 4 digits or is out of range
375	     */
376	    private void validatePostcode(String postcode, String city) {
377	        if (postcode == null) {
378	            return;
379	        }
380	        if (!postcode.matches("[0-9]{4}")) {
381	            throw new InvalidOwnerFieldsException(List.of("postcode"));
382	        }
383	        String region = city == null ? null : CITY_REGION.get(city);
384	        if (region == null) {
385	            return;
386	        }
387	        int[] range = REGION_POSTCODES.get(region);
388	        int value = Integer.parseInt(postcode);
389	        if (value < range[0] || value > range[1]) {
390	            throw new InvalidOwnerFieldsException(List.of("postcode"));
391	        }
392	    }
393	
394	    /**
395	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets are stripped.
396	     * A leading {@code '+'} and its country code are kept as-is; otherwise the country code {@code '+61'}
397	     * is assumed and a single leading {@code '0'} is dropped from the national digits. The result must be
398	     * a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} normalizes to
399	     * {@code "+61412345678"}. The E.164 string is what gets stored and returned.
400	     *
401	     * @param telephone the raw telephone value from the submitted owner payload
402	     * @return the normalized E.164 telephone number
403	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
404	     */
405	    private String normalizeTelephone(String telephone) {
406	        String raw = telephone == null ? "" : telephone.strip();
407	        boolean hasCountryCode = raw.startsWith("+");
408	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
409	        String digits;
410	        if (hasCountryCode) {
411	            digits = cleaned.substring(1);
412	        } else {
413	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
414	            digits = "61" + national;
415	        }
416	        if (!digits.matches("[0-9]{8,15}")) {
417	            throw new InvalidOwnerFieldsException(List.of("telephone"));
418	        }
419	        validateNationalNumberLength(digits);
420	        return "+" + digits;
421	    }
422	
423	    /**
424	     * Validates that the national-number portion of a normalized E.164 number (the digits after the
425	     * country calling code) has the exact length required for that country. The country code is matched
426	     * against {@link #NATIONAL_NUMBER_LENGTHS} (e.g. {@code +61} requires 9 national digits, {@code +1}
427	     * requires 10). Numbers whose country code is not listed are left to the generic length bounds.
428	     *
429	     * @param digits the normalized E.164 digits, without the leading {@code '+'}
430	     * @throws InvalidOwnerFieldsException if the national-number length is wrong for the country code
431	     */
432	    private void validateNationalNumberLength(String digits) {
433	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
434	            String countryCode = entry.getKey();
435	            if (digits.startsWith(countryCode)) {
436	                int nationalLength = digits.length() - countryCode.length();
437	                if (nationalLength != entry.getValue()) {
438	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
439	                }
440	                return;
441	            }
442	        }
443	    }
444	
445	    /**
446	     * Best-effort conversion of an existing telephone value to E.164 form for duplicate comparison,
447	     * returning {@code null} when the value cannot form a valid E.164 number.
448	     *
449	     * @param telephone an existing owner's stored telephone value
450	     * @return the E.164 form, or {@code null} if it cannot be normalized
451	     */
452	    private String toE164OrNull(String telephone) {
453	        try {
454	            return normalizeTelephone(telephone);
455	        } catch (InvalidOwnerFieldsException ex) {
456	            return null;
457	        }
458	    }
459	
460	    /**
461	     * Normalizes an optional owner email. A {@code null} value is left untouched (the field is optional).
462	     * When a value is present it must be a syntactically valid address (see {@link #EMAIL_PATTERN}); the
463	     * accepted value is trimmed and lower-cased before it is stored and returned.
464	     *
465	     * @param email the raw email value from the submitted owner payload, may be {@code null}
466	     * @return {@code null} if no email was supplied, otherwise the lower-cased email
467	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address
468	     */
469	    private String normalizeEmail(String email) {
470	        if (email == null) {
471	            return null;
472	        }
473	        String trimmed = email.strip();
474	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
475	            throw new InvalidOwnerFieldsException(List.of("email"));
476	        }
477	        return trimmed.toLowerCase(Locale.ROOT);
478	    }
479	
480	    /**
481	     * Rejects creating an owner whose derived identity key exactly equals that of any existing owner.
482	     * This single check consolidates the former separate telephone, email and household duplicate
483	     * checks: an owner is a duplicate only when its <em>whole</em> identity key
484	     * ({@code '<normalizedTelephone>|<email>|<householdId>'}) matches an existing owner's. Because the
485	     * telephone is part of the key, two members of the same household (same {@code householdId}) with
486	     * different telephones have different identity keys and are both allowed.
487	     *
488	     * <p>The new owner's telephone is already E.164-normalized and its email already lower-cased.
489	     * Existing owners' telephones are converted to E.164 form and their emails lower-cased before the
490	     * key is built, so differently-formatted representations of the same values still collide.
491	     *
492	     * @param owner the owner being created, whose email and household id contribute to the key
493	     * @param normalizedTelephone the E.164 telephone of the owner being created
494	     * @throws DuplicateOwnerIdentityException if another owner already has the same whole identity key
495	     */
496	    private void rejectDuplicateIdentity(Owner owner, String normalizedTelephone) {
497	        String newKey = identityKey(normalizedTelephone, owner.getEmail(), owner.getHouseholdId());
498	        boolean duplicate = this.clinicService.findAllOwners().stream()
499	            .anyMatch(existing -> newKey.equals(identityKey(
500	                toE164OrNull(existing.getTelephone()),
501	                existing.getEmail() == null ? null : existing.getEmail().toLowerCase(Locale.ROOT),
502	                existing.getHouseholdId())));
503	        if (duplicate) {
504	            throw new DuplicateOwnerIdentityException(newKey);
505	        }
506	    }
507	
508	    /**
509	     * Builds the duplicate-detection identity key, formatted
510	     * {@code '<normalizedTelephone>|<email>|<householdId>'}. The telephone, email and household-id
511	     * segments are each replaced with the empty string when {@code null}, so an absent email or
512	     * household id contributes an empty segment rather than the literal {@code "null"}.
513	     *
514	     * @param normalizedTelephone the E.164 telephone, may be {@code null}
515	     * @param email the lower-cased email, may be {@code null}
516	     * @param householdId the household id, may be {@code null}
517	     * @return the identity key
