1	package org.springframework.samples.petclinic.security;
2	
3	import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
4	import org.springframework.context.annotation.Bean;
5	import org.springframework.context.annotation.Configuration;
6	import org.springframework.security.config.annotation.web.builders.HttpSecurity;
7	import org.springframework.security.config.annotation.web.configurers.AbstractHttpConfigurer;
8	import org.springframework.security.config.annotation.web.configurers.HeadersConfigurer.FrameOptionsConfig;
9	import org.springframework.security.web.SecurityFilterChain;
10	
11	/**
12	 * Starting from Spring Boot 2, if Spring Security is present, endpoints are secured by default
13	 * using Spring Security’s content-negotiation strategy.
14	 */
15	@Configuration
16	@ConditionalOnProperty(name = "petclinic.security.enable", havingValue = "false")
17	public class DisableSecurityConfig {
18	
19	    @Bean
20	    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
21	        // @formatter:off
22	        http
23	            .csrf(AbstractHttpConfigurer::disable)
24	            .authorizeHttpRequests((authz) -> authz
25	                .anyRequest().permitAll()
26	            )
27	            .headers((headers) -> headers
28	                .frameOptions(FrameOptionsConfig::sameOrigin)  // to avoid setting of X-Frame-Options=deny header
29	            );
30	        // @formatter:on
31	        return http.build();
32	    }
33	}
